ACPI_STATUS AcpiPsCompleteThisOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *Next;
    ACPI_PARSE_OBJECT *Prev;
    ACPI_STATUS Status2;

    if (!WalkState || !Op)
    {
        return (AE_BAD_PARAMETER);
    }

    if (Status == AE_CTRL_PENDING)
    {
        WalkState->ControlState = Op;
        return (Status);
    }

    if (Status == AE_CTRL_TERMINATE)
    {
        return (Status);
    }

    if (WalkState->ScopeInfo->Prev && (WalkState->ScopeInfo->Prev->Scope.Obj == Op))
    {
        WalkState->ScopeInfo = WalkState->ScopeInfo->Prev;
    }

    while (Op)
    {
        if (Op->Asl.Child)
        {
            return (AE_AML_INTERNAL);
        }

        Prev = Op->Asl.Prev;
        Next = Op->Asl.Next;

        if (Op->Common.Value.ArgList)
        {
            return (AE_AML_INTERNAL);
        }

        if (Op->Asl.Parent && (Op->Asl.Parent->Common.Type == AML_TYPE_NAMED))
        {
            Op->Asl.Parent->Named.Node->ParseOp = NULL;
        }

        if (Op->Asl.Parent)
        {
            Op->Asl.Parent->Asl.Child = Op->Asl.Child;
        }

        if (Op->Asl.Child)
        {
            Op->Asl.Child->Asl.Parent = Op->Asl.Parent;
        }

        if (WalkState->ParseOpcodes && Op->Common.AmlLength)
        {
            ACPI_MEMCPY(&WalkState->ParseOpcodes[WalkState->ParseOpcodeIndex], Op->Common.AmlStart, Op->Common.AmlLength);
            WalkState->ParseOpcodeIndex += Op->Common.AmlLength;
        }

        if (Op->Asl.Dispatch.DispatchHandler)
        {
            Status2 = Op->Asl.Dispatch.DispatchHandler(WalkState, Op, Status);
            if (Status2 != AE_OK)
            {
                return (Status2);
            }
        }

        if (Op->Asl.Dispatch.DispatchType == ACPI_DISPATCH2)
        {
            if (Op->Asl.Dispatch.DispatchHandler2)
            {
                Status2 = Op->Asl.Dispatch.DispatchHandler2(WalkState, Op, Status);
                if (Status2 != AE_OK)
                {
                    return (Status2);
                }
            }
        }

        if (Op->Common.Value.Arg)
        {
            Op->Common.Value.Arg = NULL;
        }

        if (Op->Common.Value.ObjDesc)
        {
            AcpiUtReleaseDescendants(Op->Common.Value.ObjDesc);
            Op->Common.Value.ObjDesc = NULL;
        }

        if (Op->Common.Value.String)
        {
            ACPI_FREE(Op->Common.Value.String);
            Op->Common.Value.String = NULL;
        }

        if (Op->Common.Value.Buffer)
        {
            ACPI_FREE(Op->Common.Value.Buffer);
            Op->Common.Value.Buffer = NULL;
        }

        ACPI_FREE(Op);

        Op = Next;
    }

    if (Prev)
    {
        Prev->Asl.Next = NULL;
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteFinalOp(ACPI_WALK_STATE *WalkState, ACPI_PARSE_OBJECT *Op, ACPI_STATUS Status) {
    ACPI_PARSE_OBJECT *Prev;

    if (WalkState->ParserState.ScopeDepth) {
        if (WalkState->ParserState.Scope[WalkState->ParserState.ScopeDepth - 1].Op != Op) {
            return (AE_BAD_PARAMETER);
        }

        WalkState->ParserState.ScopeDepth--;

        if (WalkState->ParserState.ScopeDepth > 0) {
            WalkState->ParserState.NextOp =
                WalkState->ParserState.Scope[WalkState->ParserState.ScopeDepth - 1].Op;
        } else {
            WalkState->ParserState.NextOp = NULL;
        }
    }

    while (Op) {
        Prev = Op->Common.Next;

        if (Op->Named.Next) {
            if (WalkState->ControlState) {
                if (WalkState->ControlState->Type == ACPI_CONTROL_IF) {
                    if (Status == AE_CTRL_PENDING) {
                        WalkState->ControlState->IfValue.Value = 0;
                    }
                }
            }
        }

        if (WalkState->ControlState && WalkState->ControlState->Type == ACPI_CONTROL_ELSE) {
            if (Status == AE_CTRL_PENDING) {
                WalkState->ControlState->IfValue.Value = 0;
            }
        }

        if (WalkState->ControlState && WalkState->ControlState->Type == ACPI_CONTROL_WHILE) {
            if (Status == AE_CTRL_PENDING) {
                WalkState->ControlState->WhileValue.Value = 0;
            }
        }

        if (WalkState->ControlState && WalkState->ControlState->Type == ACPI_CONTROL_TERMINATE) {
            Status = AE_CTRL_TERMINATE;
        }

        Op = Prev;
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteScope(
    ACPI_WALK_STATE *WalkState,
    ACPI_PARSE_OBJECT *Op,
    ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *StartOp;
    ACPI_PARSE_OBJECT *LastOp;
    ACPI_PARSE_OBJECT *NextOp;
    ACPI_PARSE_OBJECT *PrevOp;

    /* Save the starting Op for tracing purposes */
    StartOp = Op;

    /* Get the last Op of this scope */
    LastOp = Op;
    while (LastOp->Common.Next) {
        LastOp = LastOp->Common.Next;
    }

    /* Walk the Op tree and complete each Op in reverse order */
    while (Op != LastOp) {
        Op = Op->Common.Next;

        /* Save the previous Op for the next iteration */
        PrevOp = Op->Common.Parent;

        /* Complete the current Op */
        if (WalkState->Control.ImmediateOps &&
            Op->Common.Value.Arg && Op->Common.Value.Arg->Node &&
            Op->Common.Value.Arg->Node->Type == ACPI_TYPE_LOCAL_SCOPE) {
            Status = AcpiPsCompleteScope(WalkState, Op, Status);
            if (ACPI_FAILURE(Status)) {
                return (Status);
            }
        }

        /* Update Op pointer to parent for next iteration */
        Op = PrevOp;
    }

    /* Remove the top scope from the scope stack */
    if (WalkState->ScopeInfo && WalkState->ScopeInfo->Scope.Aml) {
        WalkState->ScopeInfo = WalkState->ScopeInfo->Next;
    }

    /* Handle pending control flow */
    if (Status == AE_CTRL_PENDING) {
        return (Status);
    }

    /* Check if we need to terminate the walk */
    if (Status == AE_CTRL_TERMINATE) {
        return (Status);
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteScope(
    ACPI_WALK_STATE       *WalkState,
    ACPI_PARSE_OBJECT     *Op,
    ACPI_STATUS           Status)
{
    ACPI_PARSE_OBJECT     *LastOp;
    ACPI_PARSE_OBJECT     *NextOp;
    ACPI_PARSE_OBJECT     *PrevOp;
    ACPI_PARSE_OBJECT     *ScopeOp;
    ACPI_PARSE_OBJECT     *StartOp;
    ACPI_PARSE_OBJECT     *TempOp;
    ACPI_PARSE_OBJECT     *NextScopeOp;
    ACPI_PARSE_OBJECT     *ScopeStack;
    ACPI_PARSE_OBJECT     *NextScopeStack;

    /* Check if there are any open scopes */
    if (WalkState->ScopeDepth == 0)
    {
        return (Status);
    }

    /* Get the last operation in the current scope */
    LastOp = WalkState->ParserState.StartOp;
    while (LastOp->Common.Next)
    {
        LastOp = LastOp->Common.Next;
    }

    /* Check if the last operation is the same as the current operation */
    if (LastOp != Op)
    {
        return (Status);
    }

    /* Get the start operation of the current scope */
    StartOp = WalkState->ParserState.StartOp;

    /* Check if the start operation is the same as the current operation */
    if (StartOp == Op)
    {
        /* The current operation is the start of the scope, so we need to complete the scope */
        WalkState->ScopeDepth--;

        /* Get the next scope operation */
        NextScopeOp = WalkState->ScopeStack[WalkState->ScopeDepth];

        /* Check if there is a next scope operation */
        if (NextScopeOp)
        {
            /* Set the current scope operation to the next scope operation */
            WalkState->ParserState.StartOp = NextScopeOp;

            /* Set the current operation to the next scope operation */
            Op = NextScopeOp;
        }
        else
        {
            /* There is no next scope operation, so we need to terminate the parsing */
            WalkState->ParserState.StartOp = NULL;
            WalkState->ScopeDepth = 0;
            return (AE_CTRL_TERMINATE);
        }
    }

    /* Check if the current operation has a next operation */
    if (Op->Common.Next)
    {
        /* Get the next operation */
        NextOp = Op->Common.Next;

        /* Check if the next operation is the start of a new scope */
        if (NextOp->Common.Type == AML_SCOPE_OP)
        {
            /* Set the current operation to the next operation */
            Op = NextOp;

            /* Set the start of the new scope */
            WalkState->ParserState.StartOp = Op;

            /* Increment the scope depth */
            WalkState->ScopeDepth++;

            /* Set the scope stack to the current scope */
            WalkState->ScopeStack[WalkState->ScopeDepth] = Op;

            /* Set the current operation to the start of the new scope */
            Op = Op->Common.Next;
        }
        else
        {
            /* Set the current operation to the next operation */
            Op = NextOp;
        }
    }
    else
    {
        /* The current operation has no next operation, so we need to complete the scope */
        WalkState->ScopeDepth--;

        /* Get the next scope operation */
        NextScopeOp = WalkState->ScopeStack[WalkState->ScopeDepth];

        /* Check if there is a next scope operation */
        if (NextScopeOp)
        {
            /* Set the current scope operation to the next scope operation */
            WalkState->ParserState.StartOp = NextScopeOp;

            /* Set the current operation to the next scope operation */
            Op = NextScopeOp;
        }
        else
        {
            /* There is no next scope operation, so we need to terminate the parsing */
            WalkState->ParserState.StartOp = NULL;
            WalkState->ScopeDepth = 0;
            return (AE_CTRL_TERMINATE);
        }
    }

    return (Status);
}

ACPI_STATUS AcpiPsCompleteScope(
    ACPI_WALK_STATE *WalkState,
    ACPI_PARSE_OBJECT *Op,
    ACPI_STATUS Status)
{
    ACPI_PARSE_OBJECT *Next;

    if (!WalkState || !Op)
    {
        return (AE_BAD_PARAMETER);
    }

    while (Op)
    {
        Next = Op->Common.Next;

        if (Status == AE_CTRL_PENDING)
        {
            Status = AE_OK;
        }

        if (Status != AE_OK)
        {
            if (Status == AE_CTRL_TRANSFER || Status == AE_CTRL_BREAK ||
                Status == AE_CTRL_CONTINUE || Status == AE_CTRL_RETURN)
            {
                WalkState->ControlState = Status;
            }
            else if (Status != AE_CTRL_END)
            {
                WalkState->ControlState = AE_CTRL_END;
            }
        }

        if (Op->Common.Type == OP_REGION_OP)
        {
            AcpiPsPopScope(WalkState);
        }

        Op = Next;
    }

    return (Status);
}
